#define PI 3.14159265359
#define TAU 6.28318530718

// Simplex 2D noise
vec3 permute(vec3 x) { return mod(((x*34.0)+1.0)*x, 289.0); }

float snoise(vec2 v){
  const vec4 C = vec4(0.211324865405187, 0.366025403784439,
           -0.577350269189626, 0.024390243902439);
  vec2 i  = floor(v + dot(v, C.yy) );
  vec2 x0 = v -   i + dot(i, C.xx);
  vec2 i1;
  i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;
  i = mod(i, 289.0);
  vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
  + i.x + vec3(0.0, i1.x, 1.0 ));
  vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy),
    dot(x12.zw,x12.zw)), 0.0);
  m = m*m ;
  m = m*m ;
  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;
  m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
  vec3 g;
  g.x  = a0.x  * x0.x  + h.x  * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}

// Rotation matrix
mat2 rot2D(float angle) {
    float s = sin(angle), c = cos(angle);
    return mat2(c, -s, s, c);
}

// Fractal Brownian Motion
float fbm(vec2 p) {
    float sum = 0.0;
    float amp = 0.5;
    float freq = 1.0;
    for(int i = 0; i < 6; i++) {
        sum += amp * snoise(p * freq);
        amp *= 0.5;
        freq *= 2.0;
        p = rot2D(0.37) * p;
    }
    return sum;
}

// Color palette
vec3 offWhite = vec3(0.98, 0.97, 0.95);
vec3 darkPurple = vec3(0.1, 0.05, 0.15);

// Exclusion blend
vec3 exclusion(vec3 a, vec3 b) {
    return a + b - 2.0 * a * b;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / min(iResolution.x, iResolution.y);

    float time = iTime * 0.2;

    // Create two dynamic, organic shapes
    float angle = atan(uv.y, uv.x);
    float radius = length(uv);
    float segments = 14.0;

    // Pattern 1
    float distortion1 = fbm(uv * 2.0 + time) * 0.2;
    float radius1 = radius + distortion1;
    float segmentShape1 = sin(angle * segments) * 0.15;
    radius1 += segmentShape1;

    // Pattern 2
    float distortion2 = fbm(uv * 2.5 - time * 1.5) * 0.15;
    float radius2 = radius + distortion2;
    float segmentShape2 = cos(angle * (segments + 2.0)) * 0.1;
    radius2 += segmentShape2;

    // Edge glow for both patterns
    float edge1 = smoothstep(0.5, 0.48, radius1) * smoothstep(0.3, 0.32, radius1);
    edge1 *= 1.0 + 0.5 * sin(angle * segments * 2.0 + time * 3.0);

    float edge2 = smoothstep(0.55, 0.53, radius2) * smoothstep(0.35, 0.37, radius2);
    edge2 *= 1.0 + 0.5 * cos(angle * (segments + 2.0) * 2.0 - time * 2.5);

    // Color
    vec3 color1 = mix(darkPurple, offWhite, smoothstep(0.5, 0.0, radius1));
    vec3 color2 = mix(darkPurple, offWhite, smoothstep(0.55, 0.05, radius2));

    // Inner texture
    float innerPattern1 = fbm(vec2(angle * 5.0, radius1 * 10.0 - time));
    float innerPattern2 = fbm(vec2(angle * 6.0, radius2 * 12.0 + time * 0.7));

    color1 = mix(color1, offWhite, innerPattern1 * 0.5);
    color2 = mix(color2, offWhite, innerPattern2 * 0.4);

    // Edge color
    color1 = mix(color1, offWhite, edge1 * 0.8);
    color2 = mix(color2, offWhite, edge2 * 0.7);

    // Blend the two patterns using exclusion
    vec3 blendedColor = exclusion(color1, color2);

    // Background
    blendedColor = mix(darkPurple, blendedColor, smoothstep(0.8, 0.0, min(radius1, radius2)));

    // Vignette
    blendedColor *= 1.0 - 0.3 * length(uv);

    // Final adjustments
    blendedColor = pow(blendedColor, vec3(0.9)); // Subtle gamma correction
    blendedColor += vec3(0.02) * fbm(uv * 5.0 + time); // Subtle noise overlay

    fragColor = vec4(blendedColor, 1.0);
}
